/** เคอร์เนล_ค่า 안의 연결형 ไบต์_ค่า สตรีม_ค่า. Ethernet/TCP 패킷 스택이 아닌 루프백 socket เลเยอร์_ค่า. */
public final class สตรีม_เครือข่าย {
    static int[] สถานะ_ค่า = new int[16], แปลง_ค่า = new int[16], 짝 = new int[16], ชั้น_แปลง = new int[16], รอเดี๋ยว_ค่า = new int[16], เทคโนโลยีสารสนเทศ_ขอบเขต = new int[16];
    static int[] กล้องหน้า_ค่า = new int[16], หมายเลข = new int[16], ข้อมูล = new int[16 * 1024];
    static int ถัดไป_รายการ = 50000;
    static int ยืนยัน(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && สถานะ_ค่า[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int หมายเลขพอร์ต) { for (int วน_ดัชนี = 0; วน_ดัชนี < 16; วน_ดัชนี++) if (สถานะ_ค่า[วน_ดัชนี] != 0 && เทคโนโลยีสารสนเทศ_ขอบเขต[วน_ดัชนี] != 0 && แปลง_ค่า[วน_ดัชนี] == หมายเลขพอร์ต) return true; return false; }
    public static int เปิด_รายการ() {
        for (int วน_ดัชนี = 0; วน_ดัชนี < 16; วน_ดัชนี++) if (สถานะ_ค่า[วน_ดัชนี] == 0) { สถานะ_ค่า[วน_ดัชนี] = 1; ชั้น_แปลง[วน_ดัชนี] = แปลง_ค่า[วน_ดัชนี] = กล้องหน้า_ค่า[วน_ดัชนี] = หมายเลข[วน_ดัชนี] = รอเดี๋ยว_ค่า[วน_ดัชนี] = เทคโนโลยีสารสนเทศ_ขอบเขต[วน_ดัชนี] = 0; 짝[วน_ดัชนี] = -1; return วน_ดัชนี + 40; }
        return -24;
    }
    public static int ผูก_ปลายทาง(int 열린파일번호, int 통신주소, int หมายเลขพอร์ต) {
        int วน_ดัชนี = ยืนยัน(열린파일번호); if (วน_ดัชนี < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (สถานะ_ค่า[วน_ดัชนี] != 1 || หมายเลขพอร์ต < 0 || หมายเลขพอร์ต > 65535) return -22;
        if (หมายเลขพอร์ต == 0) { do { หมายเลขพอร์ต = ถัดไป_รายการ++; if (ถัดไป_รายการ > 65535) ถัดไป_รายการ = 50000; } while (사용중(หมายเลขพอร์ต)); }
        if (사용중(หมายเลขพอร์ต)) return -98; แปลง_ค่า[วน_ดัชนี] = หมายเลขพอร์ต; เทคโนโลยีสารสนเทศ_ขอบเขต[วน_ดัชนี] = 1; สถานะ_ค่า[วน_ดัชนี] = 2; return 0;
    }
    public static int รอการติดต่อ_ปลายทาง(int 열린파일번호, int รายการงานค้าง) { int วน_ดัชนี = ยืนยัน(열린파일번호); if (วน_ดัชนี < 0) return -9; if (สถานะ_ค่า[วน_ดัชนี] != 2 || รายการงานค้าง < 1) return -22; สถานะ_ค่า[วน_ดัชนี] = 3; return 0; }
    public static int เชื่อมต่อ(int 열린파일번호, int 통신주소, int หมายเลขพอร์ต) {
        int วน_ดัชนี = ยืนยัน(열린파일번호); if (วน_ดัชนี < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (หมายเลขพอร์ต < 1 || หมายเลขพอร์ต > 65535 || สถานะ_ค่า[วน_ดัชนี] > 2) return -22;
        int รับ_เพจ = -1; for (int ภายใน_ตําแหน่ง = 0; ภายใน_ตําแหน่ง < 16; ภายใน_ตําแหน่ง++) if (สถานะ_ค่า[ภายใน_ตําแหน่ง] == 3 && แปลง_ค่า[ภายใน_ตําแหน่ง] == หมายเลขพอร์ต) รับ_เพจ = ภายใน_ตําแหน่ง;
        if (รับ_เพจ < 0) return -111;
        int 대기여부 = 0; for (int ภายใน_ตําแหน่ง = 0; ภายใน_ตําแหน่ง < 16; ภายใน_ตําแหน่ง++) if (รอเดี๋ยว_ค่า[ภายใน_ตําแหน่ง] == รับ_เพจ + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (สถานะ_ค่า[วน_ดัชนี] == 1) { int 처리값 = ผูก_ปลายทาง(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int อัทเธอร์ = เปิด_รายการ(); if (อัทเธอร์ < 0) return อัทเธอร์; อัทเธอร์ -= 40;
        สถานะ_ค่า[วน_ดัชนี] = สถานะ_ค่า[อัทเธอร์] = 4; 짝[วน_ดัชนี] = อัทเธอร์; 짝[อัทเธอร์] = วน_ดัชนี; แปลง_ค่า[อัทเธอร์] = หมายเลขพอร์ต; ชั้น_แปลง[วน_ดัชนี] = หมายเลขพอร์ต; ชั้น_แปลง[อัทเธอร์] = แปลง_ค่า[วน_ดัชนี]; รอเดี๋ยว_ค่า[อัทเธอร์] = รับ_เพจ + 1; return 0;
    }
    public static int ยอมรับ_เพื่อน(int 열린파일번호) { int วน_ดัชนี = ยืนยัน(열린파일번호); if (วน_ดัชนี < 0) return -9; if (สถานะ_ค่า[วน_ดัชนี] != 3) return -22; for (int ภายใน_ตําแหน่ง = 0; ภายใน_ตําแหน่ง < 16; ภายใน_ตําแหน่ง++) if (สถานะ_ค่า[ภายใน_ตําแหน่ง] != 0 && รอเดี๋ยว_ค่า[ภายใน_ตําแหน่ง] == วน_ดัชนี + 1) { รอเดี๋ยว_ค่า[ภายใน_ตําแหน่ง] = 0; return ภายใน_ตําแหน่ง + 40; } return -11; }
    public static int เขียน(int 열린파일번호, int 항목수) {
        int วน_ดัชนี = ยืนยัน(열린파일번호); if (วน_ดัชนี < 0) return -9; if (สถานะ_ค่า[วน_ดัชนี] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int ภายใน_ตําแหน่ง = 짝[วน_ดัชนี]; if (ภายใน_ตําแหน่ง < 0) return -32; int 총수 = 1024 - หมายเลข[ภายใน_ตําแหน่ง]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int การเปรียบเทียบ_ตําแหน่ง = 0; การเปรียบเทียบ_ตําแหน่ง < 총수; การเปรียบเทียบ_ตําแหน่ง++) ข้อมูล[ภายใน_ตําแหน่ง * 1024 + (กล้องหน้า_ค่า[ภายใน_ตําแหน่ง] + หมายเลข[ภายใน_ตําแหน่ง] + การเปรียบเทียบ_ตําแหน่ง) % 1024] = วนกลับ_เครือข่าย.ส่งต่อ_ค่า_24592b8a[การเปรียบเทียบ_ตําแหน่ง]; หมายเลข[ภายใน_ตําแหน่ง] += 총수; return 총수;
    }
    public static int อ่าน(int 열린파일번호, int 항목수) {
        int วน_ดัชนี = ยืนยัน(열린파일번호); if (วน_ดัชนี < 0) return -9; if (สถานะ_ค่า[วน_ดัชนี] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (หมายเลข[วน_ดัชนี] == 0) return 짝[วน_ดัชนี] < 0 ? 0 : -11; if (항목수 > หมายเลข[วน_ดัชนี]) 항목수 = หมายเลข[วน_ดัชนี];
        for (int การเปรียบเทียบ_ตําแหน่ง = 0; การเปรียบเทียบ_ตําแหน่ง < 항목수; การเปรียบเทียบ_ตําแหน่ง++) วนกลับ_เครือข่าย.ส่งต่อ_ค่า_24592b8a[การเปรียบเทียบ_ตําแหน่ง] = ข้อมูล[วน_ดัชนี * 1024 + (กล้องหน้า_ค่า[วน_ดัชนี] + การเปรียบเทียบ_ตําแหน่ง) % 1024]; กล้องหน้า_ค่า[วน_ดัชนี] = (กล้องหน้า_ค่า[วน_ดัชนี] + 항목수) % 1024; หมายเลข[วน_ดัชนี] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int วน_ดัชนี = ยืนยัน(열린파일번호); return วน_ดัชนี < 0 ? -9 : แปลง_ค่า[วน_ดัชนี]; }
    public static int 상대창구읽기(int 열린파일번호) { int วน_ดัชนี = ยืนยัน(열린파일번호); return วน_ดัชนี < 0 ? -9 : ชั้น_แปลง[วน_ดัชนี]; }
    public static int ปิด(int 열린파일번호) {
        int วน_ดัชนี = ยืนยัน(열린파일번호); if (วน_ดัชนี < 0) return -9;
        if (สถานะ_ค่า[วน_ดัชนี] == 3) for (int ภายใน_ตําแหน่ง = 0; ภายใน_ตําแหน่ง < 16; ภายใน_ตําแหน่ง++) if (รอเดี๋ยว_ค่า[ภายใน_ตําแหน่ง] == วน_ดัชนี + 1) { if (짝[ภายใน_ตําแหน่ง] >= 0) 짝[짝[ภายใน_ตําแหน่ง]] = -1; สถานะ_ค่า[ภายใน_ตําแหน่ง] = รอเดี๋ยว_ค่า[ภายใน_ตําแหน่ง] = เทคโนโลยีสารสนเทศ_ขอบเขต[ภายใน_ตําแหน่ง] = 0; }
        if (짝[วน_ดัชนี] >= 0) 짝[짝[วน_ดัชนี]] = -1; สถานะ_ค่า[วน_ดัชนี] = เทคโนโลยีสารสนเทศ_ขอบเขต[วน_ดัชนี] = หมายเลข[วน_ดัชนี] = รอเดี๋ยว_ค่า[วน_ดัชนี] = 0; return 0;
    }
}
